\[
\vec{OA}=2\hat{i}+3\hat{j}-4\hat{k}
\]
\[
\vec{OB}=4\hat{i}-3\hat{j}+2\hat{k}
\]

\[
\overrightarrow{AB}=\vec{OB}-\vec{OA}
\]

\[
=(4\hat{i}-3\hat{j}+2\hat{k})-(2\hat{i}+3\hat{j}-4\hat{k})
\]

\[
=(4-2)\hat{i}+(-3-3)\hat{j}+(2+4)\hat{k}
\]

\[
\overrightarrow{AB}=2\hat{i}-6\hat{j}+6\hat{k}
\]

\[
|\overrightarrow{AB}|=\sqrt{2^2+(-6)^2+6^2}
\]

\[
=\sqrt{4+36+36}
\]

\[
=\sqrt{76}=2\sqrt{19}
\]

\[
\overrightarrow{AB}\text{ বরাবর একক ভেক্টর}
=\frac{\overrightarrow{AB}}{|\overrightarrow{AB}|}
\]

\[
=\frac{2\hat{i}-6\hat{j}+6\hat{k}}{2\sqrt{19}}
\]

\[
=\frac{\hat{i}-3\hat{j}+3\hat{k}}{\sqrt{19}}
\]

